<?php
require_once __DIR__ . '/config/auth.php'; wajib_login(); require_once __DIR__ . '/config/koneksi.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$id) { header('Location: dashboard.php'); exit; }
$stmt = $conn->prepare('SELECT * FROM buku WHERE id = ?'); $stmt->bind_param('i', $id); $stmt->execute(); $buku = $stmt->get_result()->fetch_assoc(); if (!$buku) { header('Location: dashboard.php'); exit; }
?>
